input.command:
cd /Users/smaschek/dev/paigasus/paigasus-core
owner=SMK1085; repo=paigasus-core; pr=47
gh api graphql -F owner="$owner" -F repo="$repo" -F pr="$pr" -f query='
query($owner:String!,$repo:String!,$pr:Int!){
  repository(owner:$owner,name:$repo){
    pullRequest(number:$pr){
      reviewThreads(first:100){
        totalCount
        nodes{
          id isResolved isOutdated
          comments(first:1){ nodes{ databaseId path line author{login} body } }
        }
      }
    }
  }
}' > /tmp/cr_threads.json 2>&1
echo "=== total review threads ==="
jq '.data.repository.pullRequest.reviewThreads.totalCount' /tmp/cr_threads.json
echo "=== threads summary (author / resolved / outdated / path:line) ==="
jq -r '.data.repository.pullRequest.reviewThreads.nodes[] | "\(.comments.nodes[0].author.login) resolved=\(.isResolved) outdated=\(.isOutdated) \(.comments.nodes[0].path):\(.comments.nodes[0].line) id=\(.id)"' /tmp/cr_threads.json
echo "=== unresolved & non-outdated CodeRabbit threads (count) ==="
jq '[.data.repository.pullRequest.reviewThreads.nodes[] | select(.isResolved==false and .isOutdated==false and (.comments.nodes[0].author.login|test("coderabbit";"i")))] | length' /tmp/cr_threads.json
